cambiar('estilo',
        '}\n.entrada img { height: 62px; display: block; margin: 0 auto 22px; }\n.entrada button { width: 100%; margin-top: 6px; }\n\n@media (max-width: 800px) {\n  .rejilla.dos, .rejilla.tres { grid-template-columns: 1fr; }\n',
        '}\n.entrada img { height: 62px; display: block; margin: 0 auto 22px; }\n.entrada button { width: 100%; margin-top: 6px; }\n/* Las pantallas de antes de entrar --crear la contrasena, pedir el\n   enlace-- viven en la misma tarjeta, con su titulo y su texto. */\n.entrada form h2 { margin: 4px 0 6px; color: var(--centauro); font-size: 18px; }\n.entrada form p { margin: 0 0 14px; }\n.entrada .centro { text-align: center; margin-top: 14px; }\n\n@media (max-width: 800px) {\n  .rejilla.dos, .rejilla.tres { grid-template-columns: 1fr; }\n')

